 int xp=stats.QuestLevel*100+stats.CurrentExperience;var turnInClick=Responses(d)[0].onClick;turnInClick.Invoke();Check(service.CurrentStage(q).id=="healing-draught"&&d.CurrentNode.id=="draught","supply turn-in advances to potion stage and refreshes dialogue");Check(inv.Count(logs)==0&&inv.Count(copper)==0&&inv.Count(potion)==1,"supply delivery consumes exactly two logs and one ore");Check(stats.QuestLevel*100+stats.CurrentExperience==xp&&!service.RewardsClaimed(q),"intermediate stage grants no completion reward");Check(service.Ready(q),"next stage is ready for stale-click test");turnInClick.Invoke();Check(service.Status(q)==QuestStatus.Active&&service.CurrentStage(q).id=="healing-draught"&&inv.Count(potion)==1,"old stage button cannot accidentally turn in newly ready stage");Check(!service.TryAdvance(q,"camp-supplies",out _),"stale stage command is rejected by service");d.Close();inv.Remove(inv.items.IndexOf(potion));Check(!service.Ready(q),"removing temporary potion restores unfinished final objective");
 await Gather(g,spring);Check(inv.Count(potion)==1&&service.Ready(q),"real spring collection readies final potion delivery");Check(!g.TryBegin(spring)&&inv.Count(potion)==1,"depleted spring cannot create duplicate quest supplies");
 for(int i=0;i<inv.items.Count;i++)if(inv.items[i]==null)inv.items[i]=logs;inv.NotifyExchange();await Interact(g,npc.transform);Check(d.CurrentNode.id=="draught","returning after gathering opens final-stage conversation");var before=inv.items.ToArray();d.Choose(0);Check(service.Status(q)==QuestStatus.Active&&!service.RewardsClaimed(q)&&inv.items.SequenceEqual(before)&&stats.QuestLevel*100+stats.CurrentExperience==xp,"full-bag final reward failure changes no items XP or completion state");Check(d.panel.npcText.text.Contains("room"),"failed final turn-in explains reward capacity");inv.Remove(inv.items.IndexOf(logs));bool reentryRejected=false,observerSeesCommit=false;Inventory.OnItemChanged observer=()=>{observerSeesCommit=service.Status(q)==QuestStatus.Completed&&service.RewardsClaimed(q)&&inv.Count(potion)==2;reentryRejected=!service.TryAdvance(q,"healing-draught",out _);};inv.onItemChangedCallback+=observer;
